    if (this.costList.isEmpty()) {
        return true;
    }
    InvWrapper playerInventory = new InvWrapper((Container)player.m_150109_());
    ICommonBuilding buildingInv = BuildingUtils.commonBuildingFromPosition(player.m_9236_(), universityPos);
    for (IResearchCost ingredient : this.costList) {
        int totalCount = 0;
        for (Item cost : ingredient.getItems()) {
            int count;
            if (buildingInv != null) {
                count = InventoryUtils.hasBuildingEnoughElseCount(buildingInv, stack -> IGlobalResearch.isUniversityResearchMatch(stack, cost), ingredient.getCount());
                totalCount += count;
            }
            if (totalCount >= ingredient.getCount()) continue;
            count = InventoryUtils.getItemCountInItemHandler((IItemHandler)playerInventory, stack -> IGlobalResearch.isPlayerResearchMatch(stack, cost));
            totalCount += count;
        }
        if (totalCount >= ingredient.getCount()) continue;
        return false;
    }
    return true;

